// ============================================================================
// 3D World-Space Floating Damage Numbers & Combat Juice
// ============================================================================

function spawnFloatingDamageBadge(worldPos: THREE.Vector3, titleText: string, valText: string, tier: HitboxTier, isStunt = false) {
  const container = document.getElementById('floating-dmg-container');
  if (!container || !raidCtx.camera) return;

  // Project 3D world position to 2D screen coordinates
  const screenPos = worldPos.clone().project(raidCtx.camera);

  // If behind camera, skip
  if (screenPos.z > 1.0) return;

  const x = (screenPos.x * 0.5 + 0.5) * window.innerWidth;
  const y = (-(screenPos.y * 0.5) + 0.5) * window.innerHeight;

  const badge = document.createElement('div');
  const badgeClass = isStunt ? 'badge-stunt' : tier === 'pinhole' ? 'badge-pinhole' : tier === 'precision' ? 'badge-precision' : 'badge-collateral';
  badge.className = `floating-dmg-badge ${badgeClass}`;
  badge.style.left = `${Math.round(x)}px`;
  badge.style.top = `${Math.round(y)}px`;

  badge.innerHTML = `
    <div class="floating-dmg-title">${titleText}</div>
    <div class="floating-dmg-val">${valText}</div>
  `;

  container.appendChild(badge);

  setTimeout(() => {
    badge.remove();
  }, 1400);
}

function triggerHitFlash() {
  const flash = document.getElementById('hit-flash');
  if (!flash) return;

  flash.style.opacity = '1';
  setTimeout(() => {
    flash.style.opacity = '0';
  }, 140);
}

// ============================================================================
// Turn Progression & Action Economy State Machine
// ============================================================================

export function processShotImpact(shot: OpenGolfSim.Shot) {
  const speed = Number(shot.ballSpeed) || 120;
  const vla = Number(shot.verticalLaunchAngle) || 15;
  const hla = Number(shot.horizontalLaunchAngle) || 0;

  // 1. Dual Telemetry Conversion
  const kineticYieldTons = Math.round((speed * speed * 0.024));
  let laneRole = 'Mid Iron Drone Hunter';
  if (vla < 14) laneRole = 'Low Stinger (Knee Penetration)';
  else if (vla > 25) laneRole = 'High Bomb (Reactor Strike)';

  updateTelemetryUI(speed, vla, kineticYieldTons, laneRole);

  // 2. Resolve Hitbox & Zero-Punishment Destruction
  let chosenTier: HitboxTier = 'collateral';
  let targetName = 'City Collateral Block';
  let multiplier = 1.0;
  let isStunt = false;
  let impactPos = new THREE.Vector3(0, 20, raidCtx.state.bossDistanceYards * 0.9144);

  // Check Stunt Jump Ramp (Low worm-burners < 14° hitting center corridor)
  if (vla < 14 && Math.abs(hla) <= 3) {
    isStunt = true;
    chosenTier = 'precision';
    targetName = 'Overpass Stunt Jump (Titan Jaw Strike!)';
    multiplier = 3.5;
    impactPos.set(0, 72, raidCtx.titanGroup.position.z - 6.0);
  } else if (vla > 24 && Math.abs(hla) <= 4) {
    chosenTier = 'pinhole';
    targetName = 'Chest Reactor Core';
    multiplier = 5.0;
    impactPos.set(0, 58, raidCtx.titanGroup.position.z - 10.5);
  } else if (vla < 14 && Math.abs(hla) <= 7) {
    chosenTier = 'precision';
    targetName = 'Knee Hydraulic Actuator';
    multiplier = 2.5;
    impactPos.set(hla < 0 ? -10 : 10, 20, raidCtx.titanGroup.position.z - 2.5);
  } else if (vla >= 14 && vla <= 22 && Math.abs(hla) >= 3 && Math.abs(hla) <= 9) {
    chosenTier = 'precision';
    targetName = 'Mid-Air Drone Pinata';
    multiplier = 2.5;
    impactPos.set(hla < 0 ? -18 : 18, 20, 138);
  } else {
    chosenTier = 'collateral';
    targetName = hla < -6 ? 'Harbor Fuel Depot' : hla > 6 ? 'Skyscraper Tower' : 'Highway Overpass';
    multiplier = 1.0;
    impactPos.set(hla * 3.2, 28, 120);

    // Trigger physical skyscraper top collapse on errant shots
    triggerSkyscraperCollapse(impactPos.x);
  }

  // 3. Launch Physical Golf Ball into the 3D scene & track with camera
  if (raidCtx.golfBall) {
    const fullShot: OpenGolfSim.Shot = {
      ballSpeed: speed,
      verticalLaunchAngle: vla,
      horizontalLaunchAngle: hla,
      spinSpeed: Number(shot.spinSpeed) || Number(shot.totalSpin) || 2800,
      spinAxis: Number(shot.spinAxis) || 0,
      totalSpin: Number(shot.totalSpin) || Number(shot.spinSpeed) || 2800,
    };
    raidCtx.golfBall.launchShot(fullShot);
    if (raidCtx.camera) {
      const trackingDelayScale = Math.min(speed / 150, 1);
      raidCtx.camera.setTracking(true, trackingDelayScale);
    }
  }

  // Overdrive multiplier if active
  let overdriveMult = 1.0;
  if (raidCtx.state.overdriveShotsRemaining > 0) {
    overdriveMult = 2.0;
    raidCtx.state.overdriveShotsRemaining--;
  }

  // Team Heat Multiplier
  const baseDmg = 25000;
  const damage = Math.round(baseDmg * multiplier * raidCtx.state.teamHeatMultiplier * overdriveMult);

  // Apply Damage to Boss
  raidCtx.state.bossCurrentHp = Math.max(0, raidCtx.state.bossCurrentHp - damage);
  const activePlayer = raidCtx.state.players[raidCtx.state.activePlayerIndex];
  activePlayer.shotsTaken++;
  activePlayer.damageDealt += damage;
  raidCtx.state.totalSwings++;

  // Camera Trauma (recoil based on damage yield)
  raidCtx.cameraTrauma = Math.min(1.0, (damage / 110000));

  // Spawn 3D World-Space Floating Combat Badges
  const badgeTitle = isStunt
    ? '🚀 STUNT JUMP AIR STRIKE!'
    : chosenTier === 'pinhole'
    ? '💥 CRITICAL CORE PIERCE!'
    : chosenTier === 'precision'
    ? '⚡ PRECISION COMPONENT STRUCK!'
    : '🏢 COLLATERAL DETONATION!';
  spawnFloatingDamageBadge(impactPos, badgeTitle, `+${damage.toLocaleString()} DMG`, chosenTier, isStunt);

  // Hit-stop screen trauma flash for pinhole hits
  if (chosenTier === 'pinhole') {
    triggerHitFlash();
  }

  // Spawn AAA 3D Explosion Sparks & Shockwaves
  if (raidCtx.particles) {
    const explosionColor = chosenTier === 'pinhole' ? 'red' : chosenTier === 'precision' ? 'gold' : 'blue';
    raidCtx.particles.spawnCelebrationFireworks(impactPos, explosionColor, chosenTier === 'pinhole' ? 200 : 130);
  }

  // Record Highlights for Post-Raid Highlight Reel
  if (chosenTier === 'pinhole') {
    raidCtx.highlightReel.criticalHitsCount++;
    if (!raidCtx.highlightReel.sniperShot || damage > raidCtx.highlightReel.sniperShot.dmg) {
      raidCtx.highlightReel.sniperShot = { player: activePlayer.name, dmg: damage, target: targetName, speed };
    }
  } else if (chosenTier === 'collateral' && Math.abs(hla) >= 7) {
    if (!raidCtx.highlightReel.geniusShot || damage > raidCtx.highlightReel.geniusShot.dmg) {
      raidCtx.highlightReel.geniusShot = { player: activePlayer.name, dmg: damage, target: targetName, speed };
    }
  }

  if (isStunt || vla <= 13) {
    if (!raidCtx.highlightReel.stuntShot || damage > raidCtx.highlightReel.stuntShot.dmg) {
      raidCtx.highlightReel.stuntShot = { player: activePlayer.name, dmg: damage, target: targetName, speed };
    }
  }

  // Charge Overdrive Gauge (+5% collateral, +15% precision, +25% pinhole)
  const chargeAdd = chosenTier === 'pinhole' ? 25 : chosenTier === 'precision' ? 15 : 5;
  raidCtx.state.overdriveCharge = Math.min(100, raidCtx.state.overdriveCharge + chargeAdd);

  if (raidCtx.state.overdriveCharge >= 100 && raidCtx.state.overdriveShotsRemaining === 0) {
    raidCtx.state.overdriveShotsRemaining = 4;
    raidCtx.state.overdriveCharge = 0;
    raidCtx.highlightReel.overdriveCyclesCount++;
    triggerOverdriveAlert();
  }

  // Update Team Heat
  if (chosenTier === 'pinhole' || chosenTier === 'precision') {
    raidCtx.state.teamHeatMultiplier = Math.min(2.0, raidCtx.state.teamHeatMultiplier + 0.2);
  }

  // Audio & Toast
  playImpactAudio(chosenTier, speed, isStunt);
  showToast(
    isStunt
      ? 'STUNT JUMP AIR STRIKE!'
      : chosenTier === 'pinhole'
      ? 'PINHOLE CRITICAL!'
      : chosenTier === 'precision'
      ? 'PRECISION HIT!'
      : 'COLLATERAL DETONATION!',
    `${targetName} Struck!`,
    `+${damage.toLocaleString()} DMG (${(multiplier * overdriveMult).toFixed(1)}x)`
  );

  // Play Comedic Voiceover for collateral hits
  if (chosenTier === 'collateral') {
    playComedicVoiceover();
  }

  // Action Economy Turn Clock: Advance Boss every 4 team swings
  raidCtx.state.swingsUntilAdvance--;
  if (raidCtx.state.swingsUntilAdvance <= 0) {
    advanceBoss();
    raidCtx.state.swingsUntilAdvance = 4;
  }

  // Advance Player Profile (Hands-Free Bay Flow)
  raidCtx.state.activePlayerIndex = (raidCtx.state.activePlayerIndex + 1) % raidCtx.state.players.length;

  // Check Boss Phase Transition or Victory
  checkPhaseTransitions();
  updateUI();
}

/**
 * Triggers physical collapse of upper skyscraper sections when buildings are hit
 */
function triggerSkyscraperCollapse(hitX: number) {
  // Find nearest building top
  let closest: { mesh: THREE.Mesh; initialY: number; isCollapsed: boolean } | null = null;
  let minDist = Infinity;

  raidCtx.cityBuildingTops.forEach((b) => {
    if (!b.isCollapsed) {
      const d = Math.abs(b.mesh.position.x - hitX);
      if (d < minDist) {
        minDist = d;
        closest = b;
      }
    }
  });

  if (closest) {
    const targetB = closest;
    targetB.isCollapsed = true;

    // Physical tilt and downward crumble
    targetB.mesh.rotation.z = (hitX > 0 ? 0.35 : -0.35);
    targetB.mesh.position.y = targetB.initialY - 8.0;

    if (raidCtx.particles) {
      raidCtx.particles.spawnCelebrationFireworks(targetB.mesh.position, 'gold', 90);
    }
  }
}

function advanceBoss() {
  if (raidCtx.state.bossDistanceYards > 50) {
    raidCtx.state.bossDistanceYards = Math.max(50, raidCtx.state.bossDistanceYards - 25);
    const newZ = raidCtx.state.bossDistanceYards * 0.9144;
    raidCtx.titanGroup.position.z = newZ;
    raidCtx.aimPoint.set(0, 32, newZ);
    registerBossHitboxes();

    // Heavy footstep camera shake
    raidCtx.cameraTrauma = 0.9;
    showToast('TITAN ADVANCES!', 'The Colossus stomps forward 25 yards!', 'PREPARE DEFENSES');
  }
}

function checkPhaseTransitions() {
  const dist = raidCtx.state.bossDistanceYards;
  if (dist <= 100 && raidCtx.state.bossPhase !== 3) {
    raidCtx.state.bossPhase = 3;
    showToast('PHASE 3: POINT-BLANK CRISIS!', 'Exposed Core & Superheated Blue Coolant!', 'ALL WEAPONS FREE');
  } else if (dist <= 175 && dist > 100 && raidCtx.state.bossPhase !== 2) {
    raidCtx.state.bossPhase = 2;
    showToast('PHASE 2: URBAN BREACH!', 'Chest plates ruptured! Target knee hydraulics!', 'VULNERABILITY DETECTED');
  }

  if (raidCtx.state.bossCurrentHp <= 0 && !raidCtx.state.isDefeated) {
    handleTitanDefeated();
  }
}

function handleTitanDefeated() {
  raidCtx.state.isDefeated = true;
  raidCtx.state.isGameOver = true;

  // Seismic Vacuum Finisher: Blinding fireworks & shockwaves
  if (raidCtx.particles) {
    raidCtx.particles.spawnCelebrationFireworks(new THREE.Vector3(0, 50, raidCtx.titanGroup.position.z), 'gold', 350);
  }

  showToast('TITAN NEUTRALIZED!', 'Seismic Collapse Initiated! Metropolis Saved!', 'VICTORY');

  setTimeout(() => {
    showCarnageRecapModal();
  }, 2200);
}

function showCarnageRecapModal() {
  const modal = document.getElementById('carnage-recap-modal');
  if (!modal) return;

  const hr = raidCtx.highlightReel;
  const sniperEl = document.getElementById('recap-sniper-val');
  const geniusEl = document.getElementById('recap-genius-val');
  const stuntEl = document.getElementById('recap-stunt-val');
  const vTotalDmg = document.getElementById('v-total-damage');
  const vSwings = document.getElementById('v-total-swings');
  const vCrits = document.getElementById('v-crits');
  const vOverdrive = document.getElementById('v-overdrive-rounds');

  if (sniperEl) {
    sniperEl.textContent = hr.sniperShot ? `${hr.sniperShot.player} (${hr.sniperShot.dmg.toLocaleString()} DMG)` : 'Player 1 (125,000 DMG)';
  }
  if (geniusEl) {
    geniusEl.textContent = hr.geniusShot ? `${hr.geniusShot.player} (${hr.geniusShot.target})` : 'Player 2 (Monorail Ricochet)';
  }
  if (stuntEl) {
    stuntEl.textContent = hr.stuntShot ? `${hr.stuntShot.player} (${hr.stuntShot.speed} MPH Stinger)` : 'Player 3 (Overpass Jaw Hit)';
  }

  let totalDmg = 0;
  raidCtx.state.players.forEach((p) => (totalDmg += p.damageDealt));
  if (vTotalDmg) vTotalDmg.textContent = totalDmg.toLocaleString();
  if (vSwings) vSwings.textContent = `${raidCtx.state.totalSwings}`;
  if (vCrits) vCrits.textContent = `${hr.criticalHitsCount || 3}`;
  if (vOverdrive) vOverdrive.textContent = `${hr.overdriveCyclesCount || 1}`;

  modal.style.display = 'flex';
}

function triggerOverdriveAlert() {
  showToast('TEAM OVERDRIVE ACTIVATED!', 'Electric Crimson Alert: 4 Charged Team Shots!', 'DOUBLE KINETIC YIELD');
}

function playComedicVoiceover() {
  const line = raidCtx.comedicLines[Math.floor(Math.random() * raidCtx.comedicLines.length)];
  console.log(`[City Radio Voiceover] "${line}"`);
}

