function updateUI() {
  const s = raidCtx.state;
  const hpFill = document.getElementById('boss-hp-fill');
  const hpText = document.getElementById('boss-hp-text');
  const distDisplay = document.getElementById('boss-dist-display');
  const phaseText = document.getElementById('boss-phase-text');
  const swingsText = document.getElementById('swings-to-advance');
  const heatBadge = document.getElementById('team-heat-badge');
  const overdriveFill = document.getElementById('overdrive-fill');
  const overdriveVal = document.getElementById('overdrive-val');
  const activeName = document.getElementById('active-player-name');

  const hpPct = Math.round((s.bossCurrentHp / s.bossMaxHp) * 100);
  if (hpFill) hpFill.style.width = `${hpPct}%`;
  if (hpText) hpText.textContent = `${s.bossCurrentHp.toLocaleString()} / ${s.bossMaxHp.toLocaleString()} HP (${hpPct}%)`;
  if (distDisplay) distDisplay.textContent = `${s.bossDistanceYards} YDS`;
  if (phaseText) phaseText.textContent = `PHASE ${s.bossPhase}: ${s.bossDistanceYards}Y STANDOFF`;
  if (swingsText) swingsText.textContent = `${s.swingsUntilAdvance}`;
  if (heatBadge) heatBadge.textContent = `🔥 HEAT ${s.teamHeatMultiplier.toFixed(1)}x`;
  if (overdriveFill) overdriveFill.style.width = `${s.overdriveCharge}%`;
  if (overdriveVal) overdriveVal.textContent = `${s.overdriveCharge}%`;
  if (activeName) {
    const p = s.players[s.activePlayerIndex];
    activeName.textContent = `${p.name} (${p.role})`;
  }
}

function updateTelemetryUI(speed: number, vla: number, yieldTons: number, laneRole: string) {
  const bs = document.getElementById('hud-ball-speed');
  const ky = document.getElementById('hud-kinetic-yield');
  const la = document.getElementById('hud-vla');
  const lr = document.getElementById('hud-lane-role');
  const td = document.getElementById('hud-total-dmg');
  const ts = document.getElementById('hud-total-shots');

  if (bs) bs.textContent = `${speed.toFixed(1)} MPH`;
  if (ky) ky.textContent = `Yield: ${yieldTons} Tons`;
  if (la) la.textContent = `${vla.toFixed(1)}°`;
  if (lr) lr.textContent = laneRole;

  let totalDmg = 0;
  raidCtx.state.players.forEach((p) => (totalDmg += p.damageDealt));
  if (td) td.textContent = totalDmg.toLocaleString();
  if (ts) ts.textContent = `${raidCtx.state.totalSwings}`;
}

let toastTimer: ReturnType<typeof setTimeout> | null = null;
function showToast(title: string, desc: string, yieldText: string) {
  const el = document.getElementById('event-toast');
  const tTitle = document.getElementById('toast-title');
  const tDesc = document.getElementById('toast-desc');
  const tYield = document.getElementById('toast-yield');

  if (!el || !tTitle || !tDesc || !tYield) return;

  tTitle.textContent = title;
  tDesc.textContent = desc;
  tYield.textContent = yieldText;
  el.style.display = 'flex';

  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    el.style.display = 'none';
  }, 2200);
}

function onShotEnded() {
  if (raidCtx.camera) {
    raidCtx.camera.setTracking(false);
    raidCtx.camera.setPositions(raidCtx.startPoint, raidCtx.aimPoint);
  }
  if (raidCtx.golfBall) {
    raidCtx.golfBall.reset(raidCtx.aimPoint, raidCtx.startPoint);
  }
}

// ============================================================================
// Initialization & AppBridge Handshake
// ============================================================================

let isRaidInitialized = false;

async function setupWorld() {
  const canvas = document.getElementById('canvas') as HTMLCanvasElement;
  raidCtx.renderer = new FuseRenderer({
    canvas,
    adaptive: true,
    renderMode: 'webgpu',
    forceWebGL: raidCtx.setupData?.backend === 'webgl',
    qualityLevel: raidCtx.setupData?.qualityLevel ?? QualityMode.Epic,
  });

  await raidCtx.renderer.init();
}

async function setupRaid() {
  if (isRaidInitialized) return;
  isRaidInitialized = true;
  document.body.style.opacity = '1';

  await setupWorld();

  raidCtx.scene = new THREE.Scene();

  // 1. Particle System for explosions & celebrations
  raidCtx.particles = new ArcadeParticleSystem(raidCtx.scene, 1200);

  // 2. Playfield & Living Metropolis
  createPlayfield();

  // 3. Directional Key Light from behind golfer forward across the bay
  const dirLight = new THREE.DirectionalLight(0xffffff, 3.2);
  dirLight.position.set(50, 140, -40);
  dirLight.target.position.set(0, 25, 160);
  raidCtx.scene.add(dirLight);
  raidCtx.scene.add(dirLight.target);
  raidCtx.dirLight = dirLight;

  // Secondary Titan Rim Light for dramatic silhouette against stadium dome
  const rimLight = new THREE.DirectionalLight(0x38bdf8, 2.5);
  rimLight.position.set(-60, 80, 280);
  rimLight.target.position.set(0, 45, 200);
  raidCtx.scene.add(rimLight);
  raidCtx.scene.add(rimLight.target);
  raidCtx.rimLight = rimLight;

  // Sky / Ground Ambient Fill
  const hemiLight = new THREE.HemisphereLight(0x93c5fd, 0x0f172a, 1.8);
  raidCtx.scene.add(hemiLight);
  raidCtx.hemiLight = hemiLight;

  // Ground Spotlight targeting the Colossus
  const titanSpot = new THREE.SpotLight(0xffeedd, 3.5, 350, Math.PI / 4, 0.4);
  titanSpot.position.set(0, 45, 60);
  titanSpot.target = raidCtx.titanGroup;
  raidCtx.scene.add(titanSpot);
  raidCtx.titanSpot = titanSpot;

  // 4. Camera (Constructed with ground mesh, wide cinematic FOV, auto-positioned at tee)
  raidCtx.camera = new ShotPerspectiveCamera({
    scene: raidCtx.groundMesh,
    far: 2000,
    fov: 34,
    autoPosition: true,
    cameraOffsetYZ: [2.6, 14],
  });
  raidCtx.camera.setPositions(raidCtx.startPoint, raidCtx.aimPoint);
  raidCtx.camera.update(0, raidCtx.startPoint, raidCtx.aimPoint);

  // 5. Golf ball with Rapier aerodynamics & ground meshes
  const groundColliders = [
    raidCtx.groundMesh!,
    ...raidCtx.cityBuildings,
    ...raidCtx.ramps,
    ...raidCtx.billboards,
  ].filter(Boolean);

  raidCtx.golfBall = new GolfBall(raidCtx.scene, {
    setupData: raidCtx.setupData || {},
    groundMeshes: groundColliders,
    waitTime: 900,
    clearTrail: 'start',
    stimpLevel: 8,
  });
  raidCtx.golfBall.reset(raidCtx.aimPoint, raidCtx.startPoint);
  raidCtx.golfBall.on('shotEnded', onShotEnded);

  // Post-processing pipeline
  if (raidCtx.renderer) {
    raidCtx.renderer.setupPostProcessing(raidCtx.scene, raidCtx.camera);
    await raidCtx.renderer.compile(raidCtx.scene, raidCtx.camera);
  }

  setupControls();
  updateUI();

  // Animation Loop
  animate(0);
  app.setLoaded();
  document.body.style.opacity = '1';
}

function setupControls() {
  // Keybindings for simulation & testing
  window.addEventListener('keydown', (e) => {
    if (e.key === '1') {
      // Stinger (<14°)
      processShotImpact({ ballSpeed: 135, verticalLaunchAngle: 11, horizontalLaunchAngle: 0, spinSpeed: 2800, spinAxis: 0 });
    } else if (e.key === '2') {
      // Mid Iron (18°)
      processShotImpact({ ballSpeed: 120, verticalLaunchAngle: 18, horizontalLaunchAngle: 4, spinSpeed: 4500, spinAxis: 0 });
    } else if (e.key === ' ' || e.key === '3') {
      // High Bomb (>25°)
      processShotImpact({ ballSpeed: 155, verticalLaunchAngle: 26, horizontalLaunchAngle: 1, spinSpeed: 2400, spinAxis: 0 });
    } else if (e.key === '4') {
      // Shank Ricochet
      processShotImpact({ ballSpeed: 110, verticalLaunchAngle: 16, horizontalLaunchAngle: -10, spinSpeed: 5200, spinAxis: 0 });
    }
  });

  // Button hooks
  document.getElementById('btn-sim-stinger')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 135, verticalLaunchAngle: 11, horizontalLaunchAngle: 0, spinSpeed: 2800, spinAxis: 0 });
  });
  document.getElementById('btn-sim-drone')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 120, verticalLaunchAngle: 18, horizontalLaunchAngle: 4, spinSpeed: 4500, spinAxis: 0 });
  });
  document.getElementById('btn-sim-high')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 155, verticalLaunchAngle: 26, horizontalLaunchAngle: 1, spinSpeed: 2400, spinAxis: 0 });
  });
  document.getElementById('btn-sim-shank')?.addEventListener('click', () => {
    processShotImpact({ ballSpeed: 110, verticalLaunchAngle: 16, horizontalLaunchAngle: -10, spinSpeed: 5200, spinAxis: 0 });
  });

  // Audio Toggle
  document.getElementById('btn-audio-toggle')?.addEventListener('click', () => {
    raidCtx.audioMuted = !raidCtx.audioMuted;
    const btn = document.getElementById('btn-audio-toggle');
    if (btn) btn.textContent = raidCtx.audioMuted ? 'Audio: OFF (M)' : 'Audio: ON (M)';
  });

  // Replay & Exit Modal Handlers
  document.getElementById('btn-replay-raid')?.addEventListener('click', () => {
    location.reload();
  });

  document.getElementById('btn-exit-hub')?.addEventListener('click', () => {
    if (window.opener || (window as unknown as { arcadeAPI: { returnToMenu: () => void } }).arcadeAPI) {
      (window as unknown as { arcadeAPI: { returnToMenu: () => void } }).arcadeAPI.returnToMenu();
    } else {
      window.location.href = '../../src/menu.html';
    }
  });
}

let elapsedTime = 0;
function animate(animDelta: number) {
  requestAnimationFrame(animate);
  raidCtx.timer.update(animDelta);
  const rawDelta = raidCtx.timer.getDelta();
  const delta = Math.max(0.001, Math.min(rawDelta > 0.0001 ? rawDelta : 0.016, 0.1));
  elapsedTime += delta;

  // 1. Update Golf Ball and Camera
  if (raidCtx.golfBall && raidCtx.camera) {
    raidCtx.golfBall.update(delta);

    if (
      raidCtx.golfBall.isShotActive &&
      raidCtx.golfBall.object &&
      Number.isFinite(raidCtx.golfBall.object.position.x) &&
      Number.isFinite(raidCtx.golfBall.object.position.y) &&
      Number.isFinite(raidCtx.golfBall.object.position.z)
    ) {
      raidCtx.camera.track(delta, raidCtx.startPoint, raidCtx.golfBall.object.position);
    } else {
      raidCtx.camera.update(delta, raidCtx.startPoint, raidCtx.aimPoint);
      raidCtx.golfBall.aimAt(raidCtx.aimPoint);
    }
  }

  // 2. Camera Trauma & Recoil (screen shake added on top)
  if (raidCtx.cameraTrauma > 0 && raidCtx.camera) {
    const shake = raidCtx.cameraTrauma * raidCtx.cameraTrauma;
    raidCtx.camera.position.x += (Math.random() - 0.5) * 0.45 * shake;
    raidCtx.camera.position.y += (Math.random() - 0.4) * 0.45 * shake;
    raidCtx.cameraTrauma = Math.max(0, raidCtx.cameraTrauma - delta * 2.0);
  }

  // 3. Update Particle System
  if (raidCtx.particles) {
    raidCtx.particles.update(delta);
  }

  // 4. Subtle Titan Living Kinematics: Breathing, Scanning Cyclops Visor, Core Rotation
  if (raidCtx.titanCoreMesh) {
    const pulse = 1.0 + Math.sin(elapsedTime * 4.5) * 0.18;
    raidCtx.titanCoreMesh.scale.set(pulse, pulse, pulse);
  }

  if (raidCtx.titanCoreRing) {
    raidCtx.titanCoreRing.rotation.z += 0.04;
  }

  // Scanning head cyclops eye
  if (raidCtx.titanHead) {
    raidCtx.titanHead.rotation.y = Math.sin(elapsedTime * 1.5) * 0.15;
  }

  if (raidCtx.state.bossPhase >= 2 && raidCtx.titanKneeLeft) {
    raidCtx.titanKneeLeft.rotation.z = Math.PI / 2 + Math.sin(elapsedTime * 8) * 0.08;
  }

  // 5. Flashing Rooftop Aviation Beacons
  const beaconOn = Math.sin(elapsedTime * 5) > 0;
  raidCtx.rooftopBeacons.forEach((b) => {
    b.visible = beaconOn;
  });

  // 6. Hovering Drones bobbing & ring rotation
  raidCtx.drones.forEach((d, i) => {
    d.group.position.y = d.basePos.y + Math.sin(elapsedTime * 2.2 + i * 1.5) * 1.2;
    d.group.rotation.y += 0.015;
    d.ring.rotation.z += 0.03;
  });

  // 7. Render
  if (raidCtx.renderer && raidCtx.scene && raidCtx.camera) {
    raidCtx.renderer.render(raidCtx.scene, raidCtx.camera);
  }
}

// AppBridge Handshake
app.initialize(() => {
  document.body.style.opacity = '1';
  if (app.appType === 'web') {
    raidCtx.setupData = generateSetupData(4);
    setupRaid();
  } else {
    setTimeout(() => {
      if (!isRaidInitialized) {
        raidCtx.setupData = generateSetupData(4);
        setupRaid();
      }
    }, 600);
  }
});

app.on('setup', (payload: any) => {
  raidCtx.setupData = payload?.setupData || generateSetupData(4);
  setupRaid();
});

app.on('shot', (shot: OpenGolfSim.Shot) => {
  processShotImpact(shot);
});

// Waggle message listener from Electron
window.addEventListener('message', (event) => {
  if (event.data?.type === 'waggle') {
    const banner = document.getElementById('waggle-banner');
    if (banner) {
      banner.style.display = 'flex';
      setTimeout(() => {
        banner.style.display = 'none';
      }, 4000);
    }
  }
});
